import { ConditionalElement } from './conditional-element';
import { clear } from './dom-manipulation';
import { isHtmlIdValid } from './is-html-id-valid';
/**
 * All widgets should extend this.  We should be very careful about adding anything to this since it is inserted into all widgets.
 * Do not add static functions to this, they should go into files full of static files such as dom-manipulation.ts
 */
export class NeonWidget extends HTMLElement {
    constructor() {
        super(...arguments);
        this.conditionalChildElements = [];
        // isInitialized is set to true the first time the widget gets added to the DOM in the connectedCallback
        this.isInitialized = false;
        // attributesChangedBeforeInit keeps track of all of the attributes set before the widget hit the DOM for the first time
        this.attributesChangedBeforeInit = new Set;
    }
    validateInputs() {
        //TODO: We may actually want to write generic handlers for required properties and required attributes.
        if (this.isIdRequired) {
            if (!isHtmlIdValid(this.getAttribute('id'))) {
                console.error('The id ' + this.getAttribute('id') + ' on ' + this.widgetTag + ' is not present or invalid');
            }
        }
    }
    /**
     * Re-renders the widget and sets it into the DOM. This wipes out any existing elements within the widget.
     */
    redraw() {
        clear(this);
        //Since we are going to be re-creating all of the conditional elements,
        //We need to reset the array that keeps track of them.
        this.conditionalChildElements = [];
        let elementsToAppend = this.render();
        if (elementsToAppend != null) {
            if (elementsToAppend instanceof Node || elementsToAppend instanceof ConditionalElement) {
                elementsToAppend = [elementsToAppend];
            }
            for (const element of elementsToAppend) {
                if (element == null) {
                    continue;
                }
                if (element instanceof Node) {
                    element.isProcessedByNeon = true;
                    this.appendChild(element);
                }
                else {
                    //it's a conditional element
                    const node = element.renderElementOrPlaceholder();
                    node.isProcessedByNeon = true;
                    this.appendChild(node);
                    this.conditionalChildElements.push(element);
                }
            }
        }
    }
    attributeChanged(attribute, oldValue, newValue) {
        // no-op
    }
    // This is a web component lifecycle function.
    // If you are extending neon-widget, please use attributeChanged to intercept the lifecycle event.
    // This method is set to private to keep all extended components from getting attribute changes during the initialization phase.
    attributeChangedCallback(attribute, oldValue, newValue) {
        if (oldValue === newValue) {
            //The attribute didn't really change. We don't care. Bye Bye.
            return;
        }
        if (!this.isInitialized) {
            this.attributesChangedBeforeInit.add(attribute);
        }
        else {
            this.attributeChanged(attribute, oldValue, newValue);
        }
    }
    //lifecycle hook
    connectedCallback() {
        this.isInitialized = true;
        this.setAttribute(this.widgetTag, '');
        this.classList.add('neon-2_20_1-component');
        setTimeout(() => {
            if (this.isConnected) {
                this.validateInputs();
            }
        }, 1000);
        this.redraw();
        for (const attribute of this.attributesChangedBeforeInit) {
            this.attributeChanged(attribute, '', this.getAttribute(attribute));
        }
        this.attributesChangedBeforeInit.clear();
    }
}
// NOTE: Normally we would have added these as member functions of neonWidget, but they are not used very often
// therefore, they are defined as static functions that can be tree shaken on widgets that do not use them
export function bindCallback(classFunction, neonWidget) {
    if (neonWidget.boundFunctionList == null) {
        neonWidget.boundFunctionList = new Map();
    }
    if (neonWidget.boundFunctionList.has(classFunction)) {
        return neonWidget.boundFunctionList.get(classFunction);
    }
    const classFunctionBinded = classFunction.bind(neonWidget);
    neonWidget.boundFunctionList.set(classFunction, classFunctionBinded);
    return classFunctionBinded;
}
// NOTE: Normally we would have added these as member functions of neonWidget, but they are not used very often
// therefore, they are defined as static functions that can be tree shaken on widgets that do not use them
export function getCallback(classFunction, neonWidget) {
    if (neonWidget.boundFunctionList == null) {
        neonWidget.boundFunctionList = new Map();
    }
    if (neonWidget.boundFunctionList.has(classFunction)) {
        return neonWidget.boundFunctionList.get(classFunction);
    }
    else {
        console.error('The boundFunctionList does not contain the function being retrieved.');
        return (event) => { };
    }
}
